import pandas as pd
import numpy as np


def Decay_Linear(x: pd.DataFrame, d: int) -> pd.DataFrame:
    weights = np.arange(1, d + 1)
    weights = weights / weights.sum()
    result = x.rolling(window=d).apply(lambda y: (y * weights).sum(), raw=True)
    return result


def Div(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    result = x / y
    return result


def Mul(x: pd.DataFrame, y: pd.DataFrame) -> pd.DataFrame:
    result = x * y
    return result


def Rank(x: pd.DataFrame) -> pd.DataFrame:
    x = x.T
    result = x.rank() / (len(x) + 1) 
    return result.T


def TS_Return(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.pct_change(d)


def TS_Var(x: pd.DataFrame, d: int) -> pd.DataFrame:
    return x.rolling(window=d).var()


def signal_momentum_adjusted_volume(Close: pd.DataFrame, Volume: pd.DataFrame) -> pd.DataFrame:
    """Adjusted volume momentum"""
    return Mul(Rank(TS_Return(Close, 20)), Rank(Decay_Linear(Volume, 20)))

def signal_volatility_adjusted_momentum(Close: pd.DataFrame) -> pd.DataFrame:
    """Volatility-adjusted momentum"""
    return Div(Rank(TS_Return(Close, 15)), Rank(TS_Var(Close, 15)))
